try{
  ClipboardPage Primary =  tools.findPage("pyWorkPage");
  ClipboardPage PropertyList_n  = Primary.getProperty(".PropertyList("+idx+")").getPageValue();
  ClipboardPage DataJSON = tools.findPage("OutputData");
  ClipboardPage DataJSONList  = DataJSON.getProperty(".pxResults("+idx+")").getPageValue();
	String IsiDataJson = DataJSONList.getString("HASIL1");
    PropertyList_n.adoptJSONObject(IsiDataJson);

} catch(InvalidStreamError e){
  oLog.error("ReloadSection:Invalid JSON Stream for data page params : "+e.getMessage());
} catch(Exception e){
  oLog.error("ReloadSection:Expection : "+e.getMessage());
}

